shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/tokio/tests/sync_broadcast.rs
+++ b/tokio/tests/sync_broadcast.rs
@@ -520,3 +520,39 @@
     assert_empty!(rx);
     assert_empty!(rx_resub);
 }
+
+#[test]
+fn resubscribe_closed_try_recv() {
+    for &capacity in &[1, 4] {
+        for messages in 0..=6 {
+            let (tx, rx) = broadcast::channel(capacity);
+            for value in 0..messages {
+                assert_ok!(tx.send(value));
+            }
+            drop(tx);
+
+            let mut rx_resub = rx.resubscribe();
+            drop(rx);
+
+            assert_closed!(rx_resub.try_recv());
+        }
+    }
+}
+
+#[test]
+fn resubscribe_closed_recv() {
+    for &capacity in &[1, 4] {
+        for messages in 0..=6 {
+            let (tx, rx) = broadcast::channel(capacity);
+            for value in 0..messages {
+                assert_ok!(tx.send(value));
+            }
+            drop(tx);
+
+            let mut rx_resub = rx.resubscribe();
+            drop(rx);
+
+            let err = assert_ready_err!(task::spawn(rx_resub.recv()).poll());
+            assert!(is_closed(err));
+        }
+    }
+}
PATCH
cargo test --offline -p tokio --test sync_broadcast --features full resubscribe_closed > /tmp/tokio-broadcast-regression.log 2>&1; result=$?; tail -n 55 /tmp/tokio-broadcast-regression.log; exit "$result"

