cd /testbed && patch -p1 <<'PATCH'
--- a/tokio/src/sync/broadcast.rs
+++ b/tokio/src/sync/broadcast.rs
@@ -666,7 +666,12 @@

     tail.rx_cnt = tail.rx_cnt.checked_add(1).expect("overflow");

-    let next = tail.pos;
+    let next = if tail.closed {
+        // Start at the close notification rather than skipping past it.
+        tail.pos.wrapping_sub(1)
+    } else {
+        tail.pos
+    };

     drop(tail);

@@ -897,6 +902,9 @@
     /// **after** it has resubscribed. This will not include elements that are
     /// in the queue of the current receiver. Consider the following example.
     ///
+    /// If the channel is closed, the returned receiver will immediately return
+    /// a closed error when receiving.
+    ///
     /// # Examples
     ///
     /// ```
PATCH
cargo test --offline -p tokio --test sync_broadcast --features full > /tmp/tokio-broadcast-tests.log 2>&1; result=$?; tail -n 36 /tmp/tokio-broadcast-tests.log; exit "$result"

